const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const memphis = ee.Geometry.Point([-90.0489, 35.1495]); // Memphis, TN coordinates
  const riverBuffer = memphis.buffer(5000); // 5km buffer around Memphis to capture Mississippi River

  // Date ranges (single day for each comparison)
  const date2014 = '2014-02-27';
  const date2019 = '2019-02-25';

  // 2. Data Acquisition - Sentinel-2 for water detection
  const s2_2014 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(riverBuffer)
    .filterDate(date2014, '2014-02-28');

  const s2_2019 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(riverBuffer)
    .filterDate(date2019, '2019-02-26');

  // Check collection sizes
  const count2014 = s2_2014.size().getInfo();
  const count2019 = s2_2019.size().getInfo();

  console.log(`2014 Images: ${count2014}, 2019 Images: ${count2019}`);

  if (count2014 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy image for each date
  const img2014 = s2_2014.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2019 = s2_2019.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const img2014_masked = maskClouds(img2014);
  const img2019_masked = maskClouds(img2019);

  // Calculate NDWI for water detection (Green - NIR) / (Green + NIR)
  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  const img2014_ndwi = addNDWI(img2014_masked);
  const img2019_ndwi = addNDWI(img2019_masked);

  // Check valid pixel counts
  const count2014_valid = img2014_ndwi.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: riverBuffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2019_valid = img2019_ndwi.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: riverBuffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Valid pixels 2014: ${count2014_valid}, 2019: ${count2019_valid}`);

  if (count2014_valid === 0 || count2019_valid === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate water extent (NDWI > 0 indicates water)
  const water2014 = img2014_ndwi.select('NDWI').gt(0);
  const water2019 = img2019_ndwi.select('NDWI').gt(0);

  const waterArea2014 = water2014.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: riverBuffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const waterArea2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: riverBuffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Water area 2014: ${waterArea2014}, 2019: ${waterArea2019}`);

  // Validation check
  if (waterArea2014 === null || waterArea2019 === null || 
      isNaN(waterArea2014) || isNaN(waterArea2019)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (waterArea2019 > waterArea2014) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
